// ============================================================
//  ⚙️  SETTINGS — edit this node, nothing else needs changing
// ============================================================
const settings = {
  // --- where results go ---
  emailTo: 'you@example.com',            // where alerts are sent
  emailFrom: 'sender@gmail.com',     // must match your SMTP login
  sheetId: 'YOUR_GOOGLE_SHEET_ID', // from the sheet URL: docs.google.com/spreadsheets/d/<THIS PART>/edit

  // --- AI screening (Google Gemini, free tier) ---
  // Alias that always points to Google's newest Flash-Lite model.
  // If it ever errors, use an exact model ID from AI Studio, e.g. 'gemini-3.5-flash-lite'.
  geminiModel: 'gemini-flash-lite-latest',
  geminiBatchSize: 12,       // jobs judged per Gemini call
  maxNewJobsPerRun: 96,      // safety cap per hourly run (rest are picked up next hour)

  // --- your filters ---
  maxYearsExperience: 1,          // fresher up to 1 year
  includeUnclearExperience: true, // keep jobs that don't state experience (flagged in the email)
  minMonthlyInr: 70000,           // 70k/month = 8.4 LPA. (10 LPA ≈ 83,333/month)
  salaryCheck: 'max',             // 'max': keep if the TOP of the salary range ≥ minimum
                                  // 'min': keep only if the BOTTOM of the range ≥ minimum
  // approximate rates used to convert foreign salaries (Nov 2026)
  usdToInr: 95,
  eurToInr: 110,
  gbpToInr: 127,

  // Job title must match at least one of these (regex, case-insensitive)
  roleKeywords: [
    'software', '\\bsde\\b', '\\bswe\\b', 'developer', 'full[\\s-]?stack', 'front[\\s-]?end',
    'back[\\s-]?end', 'forward[\\s-]?deployed', '\\bfde\\b', 'founding engineer',
    'product engineer', 'member of technical staff', '\\bmts\\b', 'web engineer',
    'application engineer', 'platform engineer', '\\bai engineer', 'new grad', 'graduate engineer',
    'react', 'node', 'mern', 'javascript', 'typescript', 'python', 'golang', 'java\\b',
  ],
  // Job title must NOT match any of these
  excludeTitle: [
    '\\bsenior\\b', '\\bsr\\b', '\\bstaff\\b', '\\bprincipal\\b', '\\blead\\b', '\\bmanager\\b',
    '\\bdirector\\b', '\\bhead\\b', '\\barchitect\\b', '\\bvp\\b', '\\bchief\\b',
    '\\bintern(ship)?\\b', '\\bapprentice', '\\b(ii|iii|iv)\\b',
    '(sde|swe|engineer|developer)[\\s-]*(2|3|4)\\b', '\\blevel\\s*(2|3|4)\\b',
    'sales engineer', 'support engineer', 'solutions? engineer', 'qa\\b', 'test engineer',
    'hardware', 'mechanical', 'electrical',
  ],

  // ---------------- sources ----------------
  // Y Combinator job board pages (YC startups, many in India, often list salary + "new grads ok")
  ycPages: [
    'https://www.ycombinator.com/jobs/role/software-engineer/india',
    'https://www.ycombinator.com/jobs/role/software-engineer/remote',
  ],
  // We Work Remotely RSS feeds
  wwrFeeds: [
    'https://weworkremotely.com/categories/remote-programming-jobs.rss',
  ],
  remoteOk: true,
  // Himalayas search: entry-level remote jobs open to India
  himalayasQueries: ['software engineer', 'full stack', 'frontend', 'backend', 'forward deployed engineer'],

  // Company career pages with public APIs (companies hiring engineers in India).
  // Add more: the slug is the last part of the company's job-board URL
  //   Greenhouse: boards.greenhouse.io/<slug>   Lever: jobs.lever.co/<slug>   Ashby: jobs.ashbyhq.com/<slug>
  greenhouse: [
    'stripe', 'databricks', 'postman', 'mongodb', 'datadog', 'samsara', 'gitlab',
    'cloudflare', 'airbnb', 'gleanwork', 'rubrik',
  ],
  lever: ['getzuma'],
  ashby: ['harvey', 'cartesia', 'anyscale'],
};

return [{ json: settings }];

// Builds the list of URLs to fetch this run (one item per request).
const s = $('Settings').first().json;
const out = [];
const add = (source, kind, url, company = '') => out.push({ json: { source, kind, url, company } });

for (const url of s.ycPages || []) add('Y Combinator', 'yc', url);
for (const url of s.wwrFeeds || []) add('WeWorkRemotely', 'wwr', url);
if (s.remoteOk) add('RemoteOK', 'remoteok', 'https://remoteok.com/api');
for (const q of s.himalayasQueries || []) {
  add('Himalayas', 'himalayas',
    'https://himalayas.app/jobs/api/search?q=' + encodeURIComponent(q) +
    '&country=IN&seniority=Entry-level&sort=recent');
}
for (const slug of s.greenhouse || []) {
  add('Greenhouse', 'greenhouse', `https://boards-api.greenhouse.io/v1/boards/${slug}/jobs`, slug); // list only (no descriptions) to keep memory low
}
for (const slug of s.lever || []) {
  add('Lever', 'lever', `https://api.lever.co/v0/postings/${slug}?mode=json`, slug);
}
for (const slug of s.ashby || []) {
  add('Ashby', 'ashby', `https://api.ashbyhq.com/posting-api/job-board/${slug}?includeCompensation=true`, slug);
}
return out;

// Turns every source's raw response into one common job format.
const inputs = $input.all();
const sourcesNode = $('Sources').all();
const jobs = [];
const failures = [];

// ---------- helpers ----------
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'", '#x27': "'", '#x2F': '/' };
function decode(str) {
  return String(str || '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&([a-z0-9#]+);/gi, (m, n) => (ENT[n] !== undefined ? ENT[n] : m));
}
function stripHtml(html) {
  return decode(String(html || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<\/(p|div|li|h\d|br|tr)>|<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .replace(/[ \t ]+/g, ' ')
    .replace(/\s*\n\s*/g, '\n')
    .trim();
}
// Keep the start of the description plus every line that talks about experience, pay or location.
function relevant(text, max = 2200) {
  const t = String(text || '');
  if (t.length <= max) return t;
  const head = t.slice(0, 700);
  const keyRe = /(year|yrs|experience|fresher|graduate|new grad|entry|junior|salary|compensation|ctc|lpa|lakh|stipend|pay|\$|₹|inr|usd|location|remote|based in|relocat|time ?zone|visa|work authori)/i;
  const lines = t.slice(700).split(/\n|(?<=\.)\s+/).filter((l) => keyRe.test(l));
  let extra = '';
  for (const l of lines) {
    if (extra.length + l.length > max - head.length) break;
    extra += l.trim() + ' | ';
  }
  return head + ' … ' + extra;
}
const cap = (s) => String(s || '').replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
const iso = (d) => { try { const x = typeof d === 'number' ? new Date(d < 1e12 ? d * 1000 : d) : new Date(d); return isNaN(x) ? '' : x.toISOString(); } catch (e) { return ''; } };
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
function job(o) {
  const j = {
    id: String(o.id),
    source: o.source,
    title: String(o.title || '').trim(),
    company: String(o.company || '').trim(),
    location: String(o.location || '').trim(),
    salary: String(o.salary || '').trim(),
    experience: String(o.experience || '').trim(),
    description: relevant(o.description || ''),
    url: o.url || '',
    postedAt: o.postedAt || '',
    remoteBoard: !!o.remoteBoard,
  };
  j.key = norm(j.company) + '|' + norm(j.title) + '|' + norm(j.location).slice(0, 40);
  return j;
}

// ---------- parsers, one per source type ----------
const parsers = {
  yc(html, src) {
    const found = new Map();
    const JOB_URL = /\/companies\/([a-z0-9-]+)\/jobs\/([A-Za-z0-9]+)(-[a-z0-9-]*)?/;
    const m = html.match(/data-page="([^"]+)"/);
    if (m) {
      let data = null;
      try { data = JSON.parse(decode(m[1])); } catch (e) { data = null; }
      const walk = (node) => {
        if (Array.isArray(node)) return node.forEach(walk);
        if (!node || typeof node !== 'object') return;
        if (typeof node.title === 'string') {
          const urlVal = Object.values(node).find((v) => typeof v === 'string' && JOB_URL.test(v));
          if (urlVal) {
            const um = urlVal.match(JOB_URL);
            const details = Object.entries(node)
              .filter(([k, v]) => ['string', 'number', 'boolean'].includes(typeof v) && String(v).length < 300 && !/logo|image|avatar/i.test(k))
              .map(([k, v]) => `${k}: ${v}`).join('; ');
            const loc = node.location || node.prettyLocation || (Array.isArray(node.locations) ? node.locations.join(' / ') : '');
            found.set(um[0], job({
              id: 'yc:' + um[2],
              source: src.source,
              title: node.title,
              company: node.companyName || (node.company && node.company.name) || cap(um[1]),
              location: typeof loc === 'string' ? loc : JSON.stringify(loc),
              salary: node.salaryRange || node.prettySalaryRange || node.salary || '',
              experience: node.minExperience || node.prettyMinExperience || node.experience || '',
              description: details,
              url: 'https://www.ycombinator.com' + um[0],
            }));
          }
        }
        Object.values(node).forEach(walk);
      };
      if (data) walk(data);
    }
    if (!found.size) {
      // Fallback: read job links straight from the HTML
      const re = /href="(?:https:\/\/www\.ycombinator\.com)?(\/companies\/([a-z0-9-]+)\/jobs\/([A-Za-z0-9]+)-([a-z0-9-]+))"/g;
      let r;
      while ((r = re.exec(html))) {
        if (found.has(r[1])) continue;
        found.set(r[1], job({
          id: 'yc:' + r[3], source: src.source, title: cap(r[4]), company: cap(r[2]),
          location: /india/.test(src.url) ? 'India' : '', description: '',
          url: 'https://www.ycombinator.com' + r[1], remoteBoard: /remote/.test(src.url),
        }));
      }
    }
    return [...found.values()];
  },

  wwr(xml, src) {
    const out = [];
    const tag = (block, name) => {
      const mm = block.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)<\\/${name}>`, 'i'));
      return mm ? decode(mm[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')).trim() : '';
    };
    for (const block of xml.split(/<item[\s>]/i).slice(1)) {
      const rawTitle = tag(block, 'title');
      const idx = rawTitle.indexOf(':');
      const company = idx > 0 ? rawTitle.slice(0, idx).trim() : '';
      const title = idx > 0 ? rawTitle.slice(idx + 1).trim() : rawTitle;
      const link = tag(block, 'link') || tag(block, 'guid');
      out.push(job({
        id: 'wwr:' + (tag(block, 'guid') || link),
        source: src.source, title, company,
        location: [tag(block, 'region'), tag(block, 'country')].filter(Boolean).join(' / '),
        description: stripHtml(tag(block, 'description')),
        url: link, postedAt: iso(tag(block, 'pubDate')), remoteBoard: true,
      }));
    }
    return out;
  },

  remoteok(text, src) {
    const arr = JSON.parse(text);
    return (Array.isArray(arr) ? arr : []).filter((x) => x && x.position).map((x) => job({
      id: 'rok:' + x.id, source: src.source, title: x.position, company: x.company,
      location: x.location || '',
      salary: x.salary_min ? `USD ${x.salary_min}${x.salary_max ? '-' + x.salary_max : ''} per year` : '',
      description: stripHtml(x.description) + (x.tags ? '\nTags: ' + x.tags.join(', ') : ''),
      url: x.url || x.apply_url, postedAt: iso(x.date || x.epoch), remoteBoard: true,
    }));
  },

  himalayas(text, src) {
    const data = JSON.parse(text);
    return (data.jobs || []).map((x) => {
      const locs = (x.locationRestrictions || []).map((l) => (typeof l === 'string' ? l : l.name || l.alpha2)).filter(Boolean);
      const sal = x.minSalary || x.maxSalary
        ? `${x.currency || ''} ${x.minSalary || ''}${x.maxSalary ? '-' + x.maxSalary : ''} ${x.salaryPeriod ? 'per ' + x.salaryPeriod : ''}`.trim() : '';
      return job({
        id: 'him:' + (x.guid || x.applicationLink), source: src.source, title: x.title, company: x.companyName,
        location: locs.length ? 'Remote: ' + locs.join(', ') : 'Remote (worldwide)',
        salary: sal, experience: Array.isArray(x.seniority) ? x.seniority.join(', ') : (x.seniority || ''),
        description: stripHtml(x.description || x.excerpt), url: x.applicationLink || x.guid,
        postedAt: iso(x.pubDate), remoteBoard: true,
      });
    });
  },

  greenhouse(text, src) {
    const data = JSON.parse(text);
    return (data.jobs || []).map((x) => job({
      id: 'gh:' + x.id, source: src.source + ' · ' + src.company, title: x.title,
      company: x.company_name || cap(src.company),
      location: (x.location && x.location.name) || '',
      description: stripHtml(decode(x.content || '')),
      url: x.absolute_url, postedAt: iso(x.first_published || x.updated_at),
    }));
  },

  lever(text, src) {
    const arr = JSON.parse(text);
    return (Array.isArray(arr) ? arr : []).map((x) => {
      const c = x.categories || {};
      const sr = x.salaryRange;
      const lists = (x.lists || []).map((l) => l.text + ': ' + stripHtml(l.content)).join('\n');
      return job({
        id: 'lever:' + x.id, source: src.source + ' · ' + src.company, title: x.text, company: cap(src.company),
        location: [c.location, ...(c.allLocations || []), x.workplaceType].filter(Boolean).join(' / '),
        salary: sr ? `${sr.currency || ''} ${sr.min || ''}-${sr.max || ''} ${sr.interval || ''}`.trim() : '',
        description: [x.descriptionPlain, lists, x.additionalPlain].filter(Boolean).join('\n'),
        url: x.hostedUrl, postedAt: iso(x.createdAt),
      });
    });
  },

  ashby(text, src) {
    const data = JSON.parse(text);
    return (data.jobs || []).filter((x) => x.isListed !== false).map((x) => {
      const comp = x.compensation || {};
      return job({
        id: 'ashby:' + x.id, source: src.source + ' · ' + src.company, title: x.title, company: cap(src.company),
        location: [x.location, ...(x.secondaryLocations || []).map((l) => l.location), x.isRemote ? 'Remote' : '']
          .filter(Boolean).join(' / '),
        salary: comp.scrapeableCompensationSalarySummary || comp.compensationTierSummary || '',
        description: x.descriptionPlain || stripHtml(x.descriptionHtml),
        url: x.jobUrl, postedAt: iso(x.publishedAt),
      });
    });
  },
};

// ---------- run ----------
for (let i = 0; i < inputs.length; i++) {
  let src;
  try { src = $('Sources').itemMatching(i).json; } catch (e) { src = (sourcesNode[i] || {}).json; }
  if (!src) continue;
  const res = inputs[i].json || {};
  const body = typeof res.data === 'string' ? res.data : (res.data ? JSON.stringify(res.data) : '');
  if (res.error || !body) {
    failures.push(`${src.source} ${src.company || ''} (${src.url}): ${res.error ? (res.error.message || JSON.stringify(res.error)).slice(0, 120) : 'empty response'}`);
    continue;
  }
  try {
    const parsed = parsers[src.kind](body, src);
    jobs.push(...parsed.filter((j) => j.title && j.url));
  } catch (e) {
    failures.push(`${src.source} ${src.company || ''} (${src.url}): could not read response – ${e.message}`);
  }
}

// failures ride along on the first item so the email can mention broken sources
if (!jobs.length) return [{ json: { _empty: true, _sourceFailures: failures } }];
return jobs.map((j, i) => ({ json: i === 0 ? { ...j, _sourceFailures: failures } : j }));

// Cheap, free filtering before anything reaches the AI:
// title must look like a software role, not senior, and location must work from India.
const s = $('Settings').first().json;
const roleRe = new RegExp(s.roleKeywords.join('|'), 'i');
const excludeRe = new RegExp(s.excludeTitle.join('|'), 'i');

const INDIA = /india|bengaluru|bangalore|hyderabad|pune|mumbai|delhi|gurgaon|gurugram|noida|chennai|kolkata|ahmedabad|jaipur|kochi|indore|chandigarh|coimbatore|thiruvananthapuram|trivandrum|mysore|mysuru|bhubaneswar|nagpur|lucknow/i;
const INDIA_CODE = /(^|[\s,(\/-])IN([\s,)\/-]|$)/;           // "Bengaluru, KA, IN" / "Remote (IN)"
const OPEN = /anywhere|worldwide|global|asia|apac|international|\bist\b/i;
const REMOTE = /remote/i;
const ELSEWHERE = /\b(us|usa|u\.s\.?|united states|canada|north america|americas|latam|latin america|europe|eu|emea|uk|united kingdom|germany|france|spain|poland|portugal|netherlands|ireland|australia|brazil|mexico|est|pst|cet)\b/i;

function locationOk(j) {
  const loc = j.location || '';
  if (INDIA.test(loc) || INDIA_CODE.test(loc) || OPEN.test(loc)) return true;
  if (!loc.trim()) return j.remoteBoard;                  // remote job board with no restriction listed
  if (REMOTE.test(loc) && !ELSEWHERE.test(loc)) return true; // plain "Remote" — let the AI read the details
  return false;
}

const seenIds = new Set();
const seenKeys = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.id || !j.title) continue;
  if (!roleRe.test(j.title) || excludeRe.test(j.title)) continue;
  if (!locationOk(j)) continue;
  if (seenIds.has(j.id) || seenKeys.has(j.key)) continue;   // same job listed twice in this run
  seenIds.add(j.id);
  seenKeys.add(j.key);
  const { _sourceFailures, ...clean } = j;
  out.push({ json: clean });
}
return out;

// Drops every job already recorded in the "Seen" tab, so you're only alerted once per job.
const s = $('Settings').first().json;
const seenIds = new Set();
const seenKeys = new Set();
for (const row of $input.all()) {
  if (row.json.id) seenIds.add(String(row.json.id));
  if (row.json.key) seenKeys.add(String(row.json.key));
}

const fresh = $('Pre-filter').all()
  .map((i) => i.json)
  .filter((j) => !seenIds.has(j.id) && !seenKeys.has(j.key))
  .sort((a, b) => String(b.postedAt).localeCompare(String(a.postedAt))); // newest first

return fresh.slice(0, s.maxNewJobsPerRun).map((j) => ({ json: j }));

// Adds the full description to each new Greenhouse job (only new, pre-filtered jobs are fetched).
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
const decode = (str) => String(str || '')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
  .replace(/&([a-z0-9#]+);/gi, (m, n) => (ENT[n] !== undefined ? ENT[n] : m));
const stripHtml = (html) => decode(String(html || '')
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<\/(p|div|li|h\d|br|tr)>|<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ')
  .replace(/\s*\n\s*/g, '\n')
  .trim();
function relevant(t, max = 2200) {
  if (t.length <= max) return t;
  const head = t.slice(0, 700);
  const keyRe = /(year|yrs|experience|fresher|graduate|new grad|entry|junior|salary|compensation|ctc|lpa|lakh|pay|\$|₹|inr|usd|location|remote|based in|relocat|time ?zone|visa|work authori)/i;
  let extra = '';
  for (const l of t.slice(700).split(/\n|\.\s+/).filter((x) => keyRe.test(x))) {
    if (extra.length + l.length > max - head.length) break;
    extra += l.trim() + ' | ';
  }
  return head + ' … ' + extra;
}

const jobsIn = $('Needs description?').all();
return $input.all().map((item, i) => {
  let job;
  try { job = $('Needs description?').itemMatching(i).json; } catch (e) { job = (jobsIn[i] || {}).json || {}; }
  const content = item.json && typeof item.json.content === 'string' ? item.json.content : '';
  const text = content ? relevant(stripHtml(decode(content))) : '';
  return { json: { ...job, description: text || job.description || '' } };
});

// Packs the new jobs into small groups and writes the screening prompt for Gemini.
const s = $('Settings').first().json;
const jobs = $input.all().map((i) => i.json);

const instructions = `You screen job postings for one candidate based in India.
Candidate: fresher / new graduate with up to ${s.maxYearsExperience} year(s) of experience.
Target roles: software engineer / SDE / SWE, forward deployed engineer (FDE), full-stack, frontend, backend, founding/product engineer, and similar hands-on software development roles.

For EVERY job in the list return one object with:
- ref: copy the job's ref exactly.
- role_match: true if it is a hands-on software engineering/development role of the kinds above. false for sales/solutions/support engineers, QA-only or manual testing, data analyst, designer, hardware, management, or non-engineering roles.
- experience_fit: "yes" if it is open to freshers/new grads/entry level, or the MINIMUM experience asked is ${s.maxYearsExperience} year(s) or less (e.g. "0-2 years", "1-3 years", "new grads ok", "Engineer I", "SDE-1", "junior", "associate"). "no" if the minimum is more than ${s.maxYearsExperience} year(s) (e.g. "2+ years", "3+ years") or it is senior/lead/staff. "unclear" if experience is not mentioned anywhere.
- experience_text: a short note of what it says, e.g. "0-1 yrs", "new grads ok", "3+ yrs", "not stated".
- location_ok: true if someone living in India can take it: based in India (on-site/hybrid/remote), or remote and open to India, Asia/APAC, or worldwide/anywhere. false if on-site outside India, or remote but restricted to other countries/regions or requiring work authorization outside India.
- salary_min_inr_month and salary_max_inr_month: the stated BASE salary converted to Indian rupees PER MONTH. Annual amounts divide by 12; hourly multiply by 160. Rates: 1 USD = ${s.usdToInr} INR, 1 EUR = ${s.eurToInr} INR, 1 GBP = ${s.gbpToInr} INR. "LPA" or "lakhs per annum" = that many lakh rupees per year; "₹1.5M" = 15 lakh per year; "K" = thousand. If only one number is given use it for both. Use null for both when no salary is stated. Ignore equity/ESOPs.
- reason: at most 15 words explaining the decision.

Return ONLY a JSON array.`;

const schema = {
  type: 'ARRAY',
  items: {
    type: 'OBJECT',
    properties: {
      ref: { type: 'STRING' },
      role_match: { type: 'BOOLEAN' },
      experience_fit: { type: 'STRING', enum: ['yes', 'no', 'unclear'] },
      experience_text: { type: 'STRING' },
      location_ok: { type: 'BOOLEAN' },
      salary_min_inr_month: { type: 'NUMBER', nullable: true },
      salary_max_inr_month: { type: 'NUMBER', nullable: true },
      reason: { type: 'STRING' },
    },
    required: ['ref', 'role_match', 'experience_fit', 'experience_text', 'location_ok', 'reason'],
  },
};

const out = [];
for (let start = 0; start < jobs.length; start += s.geminiBatchSize) {
  const group = jobs.slice(start, start + s.geminiBatchSize).map((j, k) => ({
    ref: String(start + k), // position in "All new jobs" output
    title: j.title,
    company: j.company,
    location: j.location,
    salary: j.salary || 'not stated',
    experience: j.experience || '',
    source: j.source,
    details: j.description,
  }));
  out.push({
    json: {
      refs: group.map((g) => g.ref),
      requestBody: {
        contents: [{ role: 'user', parts: [{ text: instructions + '\n\nJOBS:\n' + JSON.stringify(group, null, 1) }] }],
        generationConfig: { responseMimeType: 'application/json', responseSchema: schema },
      },
    },
  });
}
return out;

// Reads Gemini's verdicts and applies your rules (role, experience, location, salary).
// Jobs whose Gemini call failed are left out, so they are retried next hour.
const s = $('Settings').first().json;
const jobs = $('All new jobs').all().map((i) => i.json);
const now = new Date().toISOString();
const fmt = (n) => '₹' + Math.round(n).toLocaleString('en-IN');

const out = [];
const done = new Set();
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.error) continue;
  const text = (((r.candidates || [])[0] || {}).content || {}).parts
    ? r.candidates[0].content.parts.filter((p) => !p.thought).map((p) => p.text || '').join('')
    : '';
  if (!text) continue;
  let verdicts;
  try { verdicts = JSON.parse(text); } catch (e) {
    const m = text.match(/\[[\s\S]*\]/);
    try { verdicts = m ? JSON.parse(m[0]) : []; } catch (e2) { verdicts = []; }
  }
  for (const v of Array.isArray(verdicts) ? verdicts : []) {
    const job = jobs[Number(v.ref)];
    if (!job || done.has(v.ref)) continue;
    done.add(v.ref);

    const lo = typeof v.salary_min_inr_month === 'number' ? v.salary_min_inr_month : null;
    const hi = typeof v.salary_max_inr_month === 'number' ? v.salary_max_inr_month : null;
    const compare = s.salaryCheck === 'min' ? (lo ?? hi) : (hi ?? lo);
    const salaryOk = compare === null || compare >= s.minMonthlyInr;
    const expOk = v.experience_fit === 'yes' || (v.experience_fit === 'unclear' && s.includeUnclearExperience);
    const match = !!v.role_match && expOk && !!v.location_ok && salaryOk;

    const failed = [];
    if (!v.role_match) failed.push('role');
    if (!expOk) failed.push('experience');
    if (!v.location_ok) failed.push('location');
    if (!salaryOk) failed.push('salary');

    let salaryText = 'Not disclosed';
    if (lo !== null || hi !== null) {
      salaryText = lo !== null && hi !== null && lo !== hi ? `${fmt(lo)} – ${fmt(hi)}/month` : `${fmt(hi ?? lo)}/month`;
      if (job.salary) salaryText += ` (${job.salary})`;
    }

    out.push({
      json: {
        ...job,
        match,
        verdict: match ? 'MATCH' : 'rejected: ' + failed.join(', '),
        reason: v.reason || '',
        experienceText: v.experience_fit === 'unclear' ? 'Not stated' : (v.experience_text || v.experience_fit),
        salaryText,
        salaryDisclosed: lo !== null || hi !== null,
        checkedAt: now,
      },
    });
  }
}
return out;

// One row per screened job for the "Seen" tab (so it's never screened or emailed twice).
return $input.all().map((i) => ({
  json: {
    id: i.json.id,
    key: i.json.key,
    title: i.json.title,
    company: i.json.company,
    verdict: i.json.verdict,
    checked_at: i.json.checkedAt,
  },
}));

// Keeps only jobs that passed every rule and shapes them as rows for the "Jobs" tab.
const when = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });
return $input.all()
  .filter((i) => i.json.match === true)
  .map((i) => ({
    json: {
      'Found (IST)': when,
      Title: i.json.title,
      Company: i.json.company,
      Location: i.json.location,
      Salary: i.json.salaryText,
      Experience: i.json.experienceText,
      Source: i.json.source,
      Link: i.json.url,
      Why: i.json.reason,
      Status: '',
    },
  }));

// Builds one email listing every new matching job.
const jobs = $('Matching jobs').all().map((i) => i.json);
if (!jobs.length) return [];

let failures = [];
try { failures = $('Parse sources').first().json._sourceFailures || []; } catch (e) { failures = []; }

const esc = (s) => String(s || '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const when = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' });

const cards = jobs.map((j) => `
  <tr><td style="padding:14px 16px;border-bottom:1px solid #eee;">
    <div style="font-size:16px;font-weight:600;"><a href="${esc(j.Link)}" style="color:#1a56db;text-decoration:none;">${esc(j.Title)}</a></div>
    <div style="color:#333;margin-top:2px;">${esc(j.Company)} · ${esc(j.Location || 'Location not listed')}</div>
    <div style="margin-top:6px;font-size:13px;color:#555;">
      💰 ${esc(j.Salary)} &nbsp;|&nbsp; 🎓 ${esc(j.Experience)} &nbsp;|&nbsp; 🔎 ${esc(j.Source)}
    </div>
    <div style="margin-top:4px;font-size:13px;color:#777;">${esc(j.Why)}</div>
  </td></tr>`).join('');

const footer = failures.length
  ? `<p style="font-size:12px;color:#999;margin-top:16px;">Sources that failed this run (retried next hour):<br>${failures.map(esc).join('<br>')}</p>`
  : '';

const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;">
  <h2 style="margin:0 0 4px;">${jobs.length} new job${jobs.length > 1 ? 's' : ''} for you</h2>
  <div style="color:#777;font-size:13px;margin-bottom:12px;">Found ${esc(when)} IST · fresher / ≤1 yr · India or remote</div>
  <table style="border-collapse:collapse;width:100%;border:1px solid #eee;">${cards}</table>
  ${footer}
</div>`;

const names = [...new Set(jobs.map((j) => j.Company))];
return [{
  json: {
    subject: `${jobs.length} new job${jobs.length > 1 ? 's' : ''}: ${names.slice(0, 2).join(', ')}${names.length > 2 ? ' + more' : ''}`,
    html,
  },
}];
